-- CLASS_INTEGRATION_STRICT: class:fighter
-- CLASS_PACKAGE_TEST: tests/classTextNarrationAudit.test.ts
-- CLASS_WORK_STATUS: fighter:text=READY;mechanics=NOT_AUDITED; druid:text=READY;mechanics=NOT_AUDITED; cleric:text=READY;mechanics=NOT_AUDITED
-- CLASS_STATUS_LEDGER: src/rule-templates/CLASS_WORK_STATUS.md
-- PRESENTATION ONLY: Voss-authored reference copy. No CE resources/actions/values are changed here.
-- "Восс объясняет" is an authored narrator layer, not a mechanical-summary layer.
-- Exact mechanics belong in mechanical_summary/description and the "Точное правило" UI.
-- Feature authorExplanation values authored by 20260829151113 are intentionally preserved.
-- authorComment remains a separate short aside/punchline; authorDescription is the full Voss explanation.

update public.rule_templates
set author_description = case catalog_key
  when 'class:fighter' then 'Воин — редкий случай, когда человек не обещает переписать законы мира. Он просто учится драться дольше, быстрее и грязнее остальных: перевёл дух, сделал лишний рывок, пережил то, после чего другие легли, и ударил ещё раз. Удивительно надёжная философия.'
  when 'class:druid' then 'Друид смотрит на человеческое тело как на временное неудобство. Не подходит две ноги — возьмёт четыре, не хватает зубов — одолжит чужие, а если и этого мало, попросит саму природу вмешаться. Я потому и не глажу незнакомых медведей.'
  when 'class:cleric' then 'Жрец договаривается с небесами о том, чтобы законы мира на минуту сделали исключение. У него есть обычные молитвы, есть большие просьбы через Божественный канал, а домен показывает, какую именно часть божественного характера он собирается навязывать окружающим.'

  when 'subclass:fighter:arcane-archer' then 'Обычный лучник надеется, что стрела полетит прямо. Этот заранее решает, что она ещё сделает после попадания: изгонит, опутает, свернёт куда не просили или испортит цель каким-нибудь особенно образованным способом. Укрытие от такого успокаивает хуже.'
  when 'subclass:fighter:banneret' then 'Баннерет понял редкую для воина вещь: иногда полезно, чтобы рядом тоже кто-нибудь остался жив. Поэтому часть собственной стойкости и темпа он раздаёт отряду — лечит присутствием, подталкивает союзников к действию и делает общую драку менее похожей на массовые похороны.'
  when 'subclass:fighter:battle-master' then 'Мастер боя не бьёт «просто так». У каждого удара у него заранее припасена мелкая подлость: сбить, оттолкнуть, заставить промахнуться, открыть союзнику окно для атаки. Все эти неприятности оплачиваются одними и теми же костями превосходства — завещание советую писать до знакомства.'
  when 'subclass:fighter:cavalier' then 'Кавалерист хорош не потому, что умеет сидеть на лошади. Он умеет сделать участок земли вокруг себя чужой собственностью: помечает опасного врага, прикрывает союзников и очень болезненно объясняет тем, кто решил пройти мимо.'
  when 'subclass:fighter:champion' then 'Никакой тайной школы, рун или шёпота из-за грани. Чемпион просто доводит самые скучные вещи до неприличного качества: чаще попадает по-настоящему больно, лучше двигается, дольше стоит и со временем становится тем человеком, которого магия уже не делает автоматически интереснее.'
  when 'subclass:fighter:echo-knight' then 'Один воин уже неприятность. Рыцарь эха приносит на поле второго себя — достаточно настоящего, чтобы атаковать из его места, менять позицию и заставлять врага следить сразу за двумя направлениями. Если оба смотрят на вас, спор о том, какой настоящий, можно отложить.'
  when 'subclass:fighter:eldritch-knight' then 'Мистический рыцарь решил, что меч — хороший первый аргумент, но не обязан быть последним. Он подмешивает к воинской выучке магию Волшебника, привязывает к себе оружие и постепенно учится вплетать заклинания прямо в привычный обмен ударами.'
  when 'subclass:fighter:psi-warrior' then 'Пси-воин носит ещё одно оружие там, куда обычно не лезут с обыском: в собственной голове. Пси-энергией он прикрывает союзников, усиливает удары и двигает вещи без рук; чем опытнее становится, тем больше таких трюков может оплатить прежде, чем разум попросит передышку.'
  when 'subclass:fighter:rune-knight' then 'Рунный рыцарь посмотрел на великанов и решил, что лучшая часть их культуры — та, которую можно выцарапать на собственном снаряжении. Каждая руна даёт постоянную привычку и отдельный всплеск силы, а Мощь великана позволяет ненадолго решить спор ещё и ростом.'
  when 'subclass:fighter:samurai' then 'Самурай превращает самообладание в боевой ресурс, что уже звучит подозрительно полезно. Боевой дух даёт ему точность и запас стойкости, а позднее он учится выжимать из преимущества ещё больше ударов и даже вырывать себе время после того, как тело решило умереть.'

  when 'subclass:druid:circle-of-dreams' then 'Эти друиды таскают с собой кусок фейской доброты, а это сочетание слов я произношу с осторожностью. Они лечат из отдельного запаса, делают отдых безопаснее и позже начинают сокращать дорогу через пространство и сны — полезно, пока никто не спросил цену у фей.'
  when 'subclass:druid:circle-of-spores' then 'Круг Спор смотрит на разложение и видит не конец, а рабочий материал. Грибы висят вокруг друида опасным облаком, могут поселиться на нём самом ради лишней живучести и урона, а позже начинают проявлять профессиональный интерес к свежим трупам.'
  when 'subclass:druid:circle-of-the-shepherd' then 'Пастырь приходит на бой не один, даже если рядом пока никого не видно. Он зовёт духов, зверей и фей, раздаёт через тотемы защиту или поддержку и со временем делает призванную стаю крепче. Держитесь ближе к друиду: звери хотя бы знают, кого слушать.'
  when 'subclass:druid:circle-of-wildfire' then 'Друид, который приводит с собой живой пожар, хотя бы честен в выборе спутника. Вместо превращения он может позвать Огненного духа: тот кусается пламенем, таскает людей короткими прыжками сквозь огонь и помогает как сжигать, так и лечить. Воду всё равно держите рядом.'
  when 'subclass:druid:land' then 'Круг Земли каждое утро спрашивает местность, какой сегодня будет неприятностью. Выбранная земля меняет часть его магии и защиты, а сам друид умеет возвращать себе силу, поддерживать союзников и устраивать вокруг группы участок, где природа на время играет за своих.'
  when 'subclass:druid:moon' then 'Круг Луны отвечает на вопрос «зачем превращаться в зверя?» самым прямым способом: чтобы драться им лучше, чем человеком. Формы становятся опаснее и крепче, позже зверь начинает колдовать и шагать лунными скачками. Вот поэтому незнакомых медведей я не глажу особенно.'
  when 'subclass:druid:sea' then 'Этот друид не превращается в шторм — он носит шторм вокруг себя, что для окружающих различие скорее академическое. Гнев моря бьёт и отталкивает тех, кого выбрали целью, а позже приносит движение, защиту и даже возможность вручить эту бурю союзнику.'
  when 'subclass:druid:stars' then 'Круг Звёзд хотя бы использует небо практично: карта даёт ему готовую магию, а вместо обычного зверя он надевает созвездие. Лучник стреляет, Чаша лечит, Дракон помогает не терять голову и концентрацию; позже звёзды ещё и вмешиваются в чужую удачу.'

  when 'subclass:cleric:arcana-domain' then 'Одного источника чудес этому жрецу показалось мало, поэтому он полез ещё и в тайную магию. В результате получает волшебные трюки, лучше расправляется со сверхъестественной дрянью и со временем крадёт из арсенала Волшебника вещи, которые жрецам обычно не выдают.'
  when 'subclass:cleric:death-domain' then 'Служитель Смерти не занимается тонкими намёками. Его некромантия цепляет больше целей, удары несут некроз, а сопротивление этому виду боли постепенно перестаёт быть убедительным оправданием. Забавно, как много о неизбежности говорят именно живые.'
  when 'subclass:cleric:forge-domain' then 'Бог кузни хотя бы не прячет метод за метафорами: металл, огонь, молот, результат. Такой жрец благословляет оружие и броню, делает вещи из сырья и сам постепенно становится похож на очень сердитую часть кузницы, которую трудно сжечь или пробить.'
  when 'subclass:cleric:grave-domain' then 'Хранитель Могилы не любит, когда смерть забирает людей вне очереди. Поэтому тех, кто уже упал, он лечит особенно хорошо, опасные удары умеет портить, а врагам у самого края могилы помогает сделать последний шаг. Полезная избирательность.'
  when 'subclass:cleric:knowledge-domain' then 'Эти жрецы знают слишком много и всё равно добровольно идут в подземелья — прекрасное доказательство, что знание не лечит глупость. Зато оно даёт им мастерство, прорицание, телепатию, защиту разума и позже вполне буквальное преимущество от того, что они уже видели плохой исход.'
  when 'subclass:cleric:life-domain' then 'Домен Жизни делает простую вещь неприлично хорошо: не даёт вашим товарищам превратиться в воспоминания. Лечение у него весит больше, отдельное чудо раздаёт здоровье сразу, а позднее даже кости перестают притворяться, что могут выкинуть плохой результат.'
  when 'subclass:cleric:light-domain' then 'Свет истины хорош, но я предпочитаю тот, от которого врагу больно и плохо видно. Этот домен именно такой: сияние и огонь чистят пространство, вспышки мешают атакам, а позже вокруг жреца возникает область, где тьма и вражеская стойкость чувствуют себя лишними.'
  when 'subclass:cleric:nature-domain' then 'Жрец решил поговорить с природой и, к сожалению для врагов, природа ответила. Он одалживает друидские приёмы, влияет на зверей и растения, прикрывает союзников от стихий и добавляет те же стихии к собственным ударам. Дерево теперь тоже участник богословского спора.'
  when 'subclass:cleric:order-domain' then 'Когда приказ подкреплён чудом, спорить о старшинстве становится заметно опаснее. Жрец Порядка заставляет союзников действовать вовремя, врагов — слушаться, а собственную магию — встраиваться в бой так быстро, будто у всех вокруг внезапно появилась дисциплина.'
  when 'subclass:cleric:peace-domain' then 'Миротворец здесь не означает «стоять подальше от драки». Этот жрец связывает людей так, что они лучше помогают друг другу, лечатся на ходу и при необходимости буквально принимают чужой удар на себя. Мир, как выясняется, требует очень крепких доспехов.'
  when 'subclass:cleric:tempest-domain' then 'Если молитва отвечает громом, я не прошу повторить погромче. Жрец Бури отвечает атакующим молнией, умеет заставить стихийный удар выдать максимум, отбрасывает врагов электричеством и со временем получает ещё один довод в споре с землёй — полёт.'
  when 'subclass:cleric:trickery-domain' then 'Бог Обмана хотя бы честно предупреждает названием. Его жрец прячется лучше, выпускает двойника, колдует из чужой позиции и при нужде меняется с иллюзией местами. Враг тратит время на неправильную цель — а это почти всегда самый дорогой ресурс в бою.'
  when 'subclass:cleric:twilight-domain' then 'Сумерки удобны: достаточно света, чтобы видеть проблему, и достаточно тьмы, чтобы она не сразу увидела вас. Этот жрец приносит с собой именно такую границу — огромное зрение в темноте, ранний ход и святилище, которое каждый раунд держит группу на ногах.'
  when 'subclass:cleric:war-domain' then 'Редкий жрец, который не притворяется, будто богословский спор обязательно закончится словами. Домен Войны помогает попадать, атаковать ещё раз, держать боевые чары без обычной возни и со временем делает самого жреца заметно труднее разобрать оружием на части.'
  else author_description
end,
updated_at = now()
where catalog_key ~ '^(class|subclass):(fighter|druid|cleric)(:|$)';

with replacements(catalog_key, level, label, explanation) as (
  values
    ('class:cleric', 6, 'Способность домена', 'К шестому уровню выбранный бог уже успевает привыкнуть, что жрец регулярно просит новые способы вмешиваться в чужие дела. Поэтому домен раскрывает следующую свою способность — не новый путь, а ещё один инструмент того же обещания.'),
    ('class:cleric', 17, 'Способность домена', 'К семнадцатому уровню домен перестаёт выдавать мелочь. Жрец получает одну из своих поздних фирменных способностей — тот самый момент, когда прежняя вера начинает выглядеть для окружающих как очень конкретная угроза.'),
    ('class:fighter', 7, 'Способность Воинского архетипа', 'Архетип уже выбран, и теперь начинает показывать, зачем вообще требовал отдельного названия. На седьмом уровне воин получает следующий приём своего пути — обычно именно здесь привычная драка приобретает неприятную для врага специализацию.'),
    ('class:fighter', 10, 'Способность Воинского архетипа', 'К десятому уровню выбранный архетип успевает превратиться из манеры драться в дурную привычку для всех напротив. Воин получает следующую способность того же пути и становится ещё хуже похож на человека, которого можно решить одним хорошим ударом.'),
    ('class:fighter', 15, 'Способность Воинского архетипа', 'На пятнадцатом уровне архетип выдаёт одну из поздних своих уловок. Если враг до сих пор понял, как именно дерётся этот воин, самое время испортить ему чувство уверенности новым правилом.'),
    ('class:fighter', 18, 'Способность Воинского архетипа', 'К восемнадцатому уровню выбранный путь уже не объясняет себя — он ставит точку. Воин получает вершину своего архетипа, и обычно после этого спор о том, насколько серьёзна его специализация, ведут уже наследники противника.'),
    ('subclass:druid:circle-of-spores', 14, 'Грибковое тело', 'К этому времени грибы настолько освоились в друиде, что некоторые обычные способы испортить живое тело просто перестают работать как положено. Яд, слепота, глухота и испуг встречают заметно меньше понимания, а критический удар чаще обнаруживает, что цель уже не вполне уважает нормальную анатомию.')
)
update public.rule_template_levels l
set mechanics = (
  select coalesce(jsonb_agg(
    case
      when m.elem->>'type' = 'grant'
       and m.elem->>'target' = 'feature'
       and m.elem->'payload'->>'label' = r.label
      then jsonb_set(
        jsonb_set(
          m.elem,
          '{payload}',
          coalesce(m.elem->'payload', '{}'::jsonb) || jsonb_build_object('authorExplanation', r.explanation),
          true
        ),
        '{presentation}',
        coalesce(m.elem->'presentation', '{}'::jsonb) || jsonb_build_object('authorExplanation', r.explanation),
        true
      )
      else m.elem
    end
    order by m.ord
  ), '[]'::jsonb)
  from jsonb_array_elements(coalesce(l.mechanics, '[]'::jsonb)) with ordinality as m(elem, ord)
)
from public.rule_templates t, replacements r
where t.id = l.template_id
  and t.catalog_key = r.catalog_key
  and l.level = r.level;
